 props=dict(line.split('=',1) for line in command(['systemctl','show',UNIT,'-p','MainPID','-p','ActiveState','-p','User']).splitlines())
 pid=int(props['MainPID']);assert props['ActiveState']=='active' and props['User']=='jwk' and pid==old['serverPid']
 assert sha(P('/proc',str(pid),'exe'))==inputs['native_inputs']['server']['sha256']
