 for state in ('running','paused'):assert api('/v2/sandboxes?limit=1&state='+state)[1]==[],'Existing '+state+' sandboxes'
 lockpath=BASE/'scripts/.run.lock';st=lockpath.lstat();assert stat.S_ISREG(st.st_mode) and st.st_uid==1002
 lockfd=os.open(lockpath,os.O_RDWR|os.O_NOFOLLOW);fcntl.flock(lockfd,fcntl.LOCK_EX|fcntl.LOCK_NB)
 for proc in P('/proc').iterdir():
  if not proc.name.isdigit():continue
