  for _ in range(240):
   try:
    newpid=int(command(['systemctl','show',UNIT,'-p','MainPID','--value']).strip())
    if newpid and newpid!=pid and sha(P('/proc',str(newpid),'exe'))==inputs['native_inputs']['server']['sha256'] and api('/health')[0]==204:healthy=True;break
   except (OSError,AssertionError,ValueError):pass
   time.sleep(.5)
  assert healthy,'Detailed runtime did not become healthy'
  rawenv=(P('/proc',str(newpid),'environ')).read_bytes().split(b'\0')
  logging={}
  for row in rawenv:
   if b'=' in row:
    a,b=row.split(b'=',1)
    if a in (b'RUST_LOG',b'AENV_LOG_FORMAT',b'AENV_LOG_SPAN_EVENTS'):logging[a.decode()]=b.decode()
  assert logging['AENV_LOG_FORMAT']=='json' and logging['AENV_LOG_SPAN_EVENTS']=='close'
  outcome.update(newServerPid=newpid,serviceRestarted=True,logging=logging,netns=os.stat('/proc/'+str(newpid)+'/ns/net').st_ino)
  stable=0;last=-1
  for _ in range(120):
   fc=[]
   for proc in P('/proc').iterdir():
    if not proc.name.isdigit():continue
    try:
     if proc.stat().st_uid==1002 and (proc/'comm').read_text().strip()=='firecracker' and P(os.readlink(proc/'cwd')).is_relative_to(BASE/'fc'):fc.append(int(proc.name))
    except OSError:pass
   stable=stable+1 if len(fc)==last and len(fc)>=300 else 0;last=len(fc)
   if stable>=3:break
   time.sleep(1)
  assert stable>=3,'FC startup pool did not stabilize';outcome['initialFC']=last
  identity=json.loads((BASE/'r/runtime-attestation008.json').read_text());assert identity['pid']==newpid and identity['uid']==1002
  userfile(directory/'runtime-identity.json',json.dumps(identity,indent=2)+'\n')
  worker_env={'PATH':env['PATH'],'LANG':'C.UTF-8','HOME':pwd.getpwnam('jwk').pw_dir,'USER':'jwk','LOGNAME':'jwk','NO_PROXY':'localhost,127.0.0.1','no_proxy':'localhost,127.0.0.1'}
  args=['nsenter','--target',str(newpid),'--mount','--net','--','setpriv','--reuid=1002','--regid=1002','--clear-groups','--inh-caps=-all','--ambient-caps=-all','--bounding-set=-all','--no-new-privs','/usr/bin/python3','-I','-B',str(directory/'wikidata024_worker.py')]
  with (directory/'worker.log').open('xb') as log:r=subprocess.run(args,env=worker_env,stdout=log,stderr=subprocess.STDOUT,timeout=7200)
  outcome['workerExitCode']=r.returncode
  metadata=json.loads((BASE/'wikidata024/result.json').read_text());outcome['worker']=metadata
  time.sleep(1)
  offset=metadata.get('formalServerLogOffset',initial_log_offset);logpath=BASE/'logs/server.log';length=logpath.stat().st_size-offset
  assert 0<=length<=64*1024**2,'Detailed log size exceeds bound; preserve on Y'
  with logpath.open('rb') as f:f.seek(offset);logs=f.read(length)
  userfile(directory/'server-formal.jsonl',logs)
  outcome['formalLogBytes']=len(logs);outcome['formalLogSha256']=hashlib.sha256(logs).hexdigest()
  summary=json.loads((BASE/'results/wikidata024/formal/summary.json').read_text());outcome['summary']=summary
  ops=[json.loads(line) for line in (BASE/'results/wikidata024/formal/operations.jsonl').read_text().splitlines()]
