  roots={'create_sandbox':'create','pause_sandbox':'pause','resume_sandbox':'resume','delete_sandbox':'delete'};counts=collections.Counter();invalid=0
  for line in logs.splitlines():
   try:event=json.loads(line)
   except ValueError:invalid+=1;continue
   span=event.get('span') or {};fields=event.get('fields') or {}
   if fields.get('message')=='close' and span.get('name') in roots and (span.get('sandbox_id'),roots[span['name']]) in selected:counts[roots[span['name']]]+=1
  outcome['rootSpanCoverage']=dict(counts);outcome['invalidJsonLines']=invalid
  assert r.returncode==0 and summary['valid'] and not summary['remaining_sandboxes'],'Diagnostic benchmark invalid'
  assert len(selected)==400 and all(counts[p]==100 for p in ('create','pause','resume','delete')) and not invalid,'Root span coverage incomplete'
